#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

#define INF ((ll)4e18)

typedef struct Edge {
    int to;
    int next;
    char type; /* 'N' or 'L' */
} Edge;

typedef struct StateEdge {
    int to;
    int next;
    int w; /* 0 or 1 */
} StateEdge;

typedef struct Deque {
    int *a;
    int head, tail, cap;
} Deque;

static void dq_init(Deque *dq, int cap) {
    dq->a = (int*)malloc(sizeof(int) * cap);
    dq->head = dq->tail = cap / 2;
    dq->cap = cap;
}
static int dq_empty(Deque *dq) {
    return dq->head == dq->tail;
}
static void dq_push_front(Deque *dq, int x) {
    dq->a[--dq->head] = x;
}
static void dq_push_back(Deque *dq, int x) {
    dq->a[dq->tail++] = x;
}
static int dq_pop_front(Deque *dq) {
    return dq->a[dq->head++];
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int S, C;
    scanf("%d %d", &S, &C); /* Natsume start, Lennon start */

    /* Original graph on rooms 0..n */
    int V = n + 1;
    int *head = (int*)malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) head[i] = -1;

    Edge *edges = (Edge*)malloc(sizeof(Edge) * (2 * m));
    int ecnt = 0;

    int summer_room = -1;

    for (int i = 0; i < m; i++) {
        int u, v;
        char t[4];
        scanf("%d %d %s", &u, &v, t);

        edges[ecnt].to = v;
        edges[ecnt].type = t[0];
        edges[ecnt].next = head[u];
        head[u] = ecnt++;

        edges[ecnt].to = u;
        edges[ecnt].type = t[0];
        edges[ecnt].next = head[v];
        head[v] = ecnt++;

        if (u == 0) summer_room = v;
        if (v == 0) summer_room = u;
    }

    /*
      Key idea:
      A normal door can be used by Lennon iff Natsume has opened it, which requires
      Natsume to be able to reach one endpoint through already-open normal doors and
      any small doors are impossible for Natsume.

      We model states as pairs:
        (cat_room, human_component)

      human_component = connected component in graph of only normal doors.
      Since once Natsume opens a normal door incident to her reachable area, that door
      becomes part of her reachable area too, effectively expanding within the same
      normal-door connected component. Therefore the exact room of Natsume inside that
      component does not matter.

      From state (c, hc):
      - Lennon can move through an L-door c->c' at cost 0, state (c', hc).
      - If c has an N-door to c', and room c belongs to hc, then Natsume can open it
        and Lennon can pass: cost 1, new state (c', hc') where hc' is the normal-door
        component of c' (same as hc, actually for N-edge between components impossible;
        by definition N-edge lies inside one component). More generally we can just use
        comp[c'].

      Since normal-door components are maximal connected components of N-edges,
      any N-edge always stays inside one component. Thus opening one additional normal
      door is only needed when Lennon traverses an N-edge whose endpoint room is in
      Natsume's current component and the cat crosses that specific closed door.
      After crossing, Lennon may be elsewhere, but Natsume's reachable component
      remains the same.

      So state reduces to (cat_room), but cat can traverse N-edge only if current room
      is in Natsume's component. Natsume's component itself can change only if Lennon
      crosses the unique Door to Summer? No, Natsume moves only via N-doors, all inside
      her starting normal component forever. She cannot cross L-doors. Opening doors
      does not create new N-connections outside her component; all N-edges are already
      part of that component relation. Hence Natsume can only ever open N-doors incident
      to rooms in her starting N-component.

      Therefore Lennon can:
      - move freely on L-doors anywhere,
      - traverse an N-door at cost 1 only if that door is incident to a room in
        Natsume's starting N-component (equivalently both endpoints are in it, since
        N-edge stays within one N-component).

      Then the problem is shortest path for Lennon where:
      - L-edge cost 0
      - N-edge cost 1 if inside Natsume component, otherwise unusable.

      This follows because Natsume's ability never expands beyond her N-component.
    */

    /* Compute connected components using only N-doors */
    int *comp = (int*)malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) comp[i] = -1;

    int *queue = (int*)malloc(sizeof(int) * V);
    int comp_cnt = 0;

    for (int i = 0; i < V; i++) {
        if (comp[i] != -1) continue;
        int qh = 0, qt = 0;
        queue[qt++] = i;
        comp[i] = comp_cnt;
        while (qh < qt) {
            int u = queue[qh++];
            for (int e = head[u]; e != -1; e = edges[e].next) {
                if (edges[e].type != 'N') continue;
                int v = edges[e].to;
                if (comp[v] == -1) {
                    comp[v] = comp_cnt;
                    queue[qt++] = v;
                }
            }
        }
        comp_cnt++;
    }

    int natsume_comp = comp[S];

    /* Build 0-1 graph for Lennon */
    int *shead = (int*)malloc(sizeof(int) * V);
    for (int i = 0; i < V; i++) shead[i] = -1;
    StateEdge *sedges = (StateEdge*)malloc(sizeof(StateEdge) * (2 * m));
    int secnt = 0;

    for (int u = 0; u < V; u++) {
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            char t = edges[e].type;
            if (t == 'L') {
                sedges[secnt].to = v;
                sedges[secnt].w = 0;
                sedges[secnt].next = shead[u];
                shead[u] = secnt++;
            } else {
                if (comp[u] == natsume_comp) {
                    sedges[secnt].to = v;
                    sedges[secnt].w = 1;
                    sedges[secnt].next = shead[u];
                    shead[u] = secnt++;
                }
            }
        }
    }

    /* 0-1 BFS from Lennon start to room 0 */
    ll *dist = (ll*)malloc(sizeof(ll) * V);
    for (int i = 0; i < V; i++) dist[i] = INF;

    Deque dq;
    dq_init(&dq, 4 * V + 10);

    dist[C] = 0;
    dq_push_front(&dq, C);

    while (!dq_empty(&dq)) {
        int u = dq_pop_front(&dq);
        ll du = dist[u];

        for (int e = shead[u]; e != -1; e = sedges[e].next) {
            int v = sedges[e].to;
            int w = sedges[e].w;
            if (dist[v] > du + w) {
                dist[v] = du + w;
                if (w == 0) dq_push_front(&dq, v);
                else dq_push_back(&dq, v);
            }
        }
    }

    printf("%lld\n", dist[0]);

    free(head);
    free(edges);
    free(comp);
    free(queue);
    free(shead);
    free(sedges);
    free(dist);
    free(dq.a);
    (void)summer_room;
    return 0;
}

