// Lennon moves via N: only if natsume is adjacent (same room as one end)

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    int startN, startL;
    cin >> startN >> startL;

    vector<vector<pair<int, char>>> adj(n + 1);
    for (int i = 0; i < m; i++) {
        int u, v;
        char t;
        cin >> u >> v >> t;
        adj[u].push_back({v, t});
        adj[v].push_back({u, t});
    }

    const int INF = 1e9;
    // dist[room][0] = Natsume not in same room, dist[room][1] = Natsume in same room
    vector<vector<int>> dist(n + 1, vector<int>(2, INF));
    deque<tuple<int, int, int>> dq; // room, has_natsume, cost

    dist[startL][0] = 0;
    dq.push_front({startL, 0, 0});

    while (!dq.empty()) {
        auto [u, hasN, cost] = dq.front();
        dq.pop_front();
        if (cost != dist[u][hasN]) continue;

        // If we reach room 0 (Door to Summer), answer found
        if (u == 0) {
            cout << cost << "\n";
            return 0;
        }

        for (auto [v, type] : adj[u]) {
            if (type == 'L') {
                // Lennon can pass freely
                if (dist[v][hasN] > cost) {
                    dist[v][hasN] = cost;
                    dq.push_front({v, hasN, cost});
                }
            } else { // type == 'N'
                if (hasN) {
                    // Natsume is here, can open normal door
                    if (dist[v][1] > cost) {
                        dist[v][1] = cost;
                        dq.push_front({v, 1, cost});
                    }
                } else {
                    // No Natsume — need to call her, cost +1, and she comes to this room
                    if (dist[v][1] > cost + 1) {
                        dist[v][1] = cost + 1;
                        dq.push_back({v, 1, cost + 1});
                    }
                }
            }
        }

        // If Natsume is not here, she can move to this room via normal doors
        if (!hasN) {
            for (auto [v, type] : adj[u]) {
                if (type == 'N') {
                    // Natsume moves from u to v, cost unchanged because she moves freely
                    if (dist[v][0] > cost) {
                        dist[v][0] = cost;
                        dq.push_front({v, 0, cost});
                    }
                }
            }
        }
    }

    // Should never happen per problem statement
    cout << -1 << "\n";
    return 0;
}

