int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    int sN, sL;
    cin >> sN >> sL;

    vector<vector<Edge>> g(n + 1);
    int summerRoom = -1; // the unique room connected to 0 by the Door to Summer
    char summerType = '?';

    for (int i = 0; i < m; ++i) {
        int u, v;
        char c;
        cin >> u >> v >> c;

        if (u == 0 || v == 0) {
            int other = (u == 0 ? v : u);
            summerRoom = other;
            summerType = c;
        } else {
            g[u].push_back({v, c});
            g[v].push_back({u, c});
        }
    }

    // 0-1 BFS for Lennon alone:
    // cost = number of normal doors on the path, because each such door must be opened by Natsume.
    vector<int> distL(n + 1, INF);
    deque<int> dq;
    distL[sL] = 0;
    dq.push_back(sL);

    while (!dq.empty()) {
        int u = dq.front();
        dq.pop_front();

        for (auto &e : g[u]) {
            int w = (e.type == 'L' ? 0 : 1);
            if (distL[e.to] > distL[u] + w) {
                distL[e.to] = distL[u] + w;
                if (w == 0) dq.push_front(e.to);
                else dq.push_back(e.to);
            }
        }
    }

    // Rooms reachable by Natsume using only normal doors after opening them.
    // She cannot pass small doors.
    vector<char> reachN(n + 1, 0);
    queue<int> q;
    reachN[sN] = 1;
    q.push(sN);

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (auto &e : g[u]) {
            if (e.type == 'N' && !reachN[e.to]) {
                reachN[e.to] = 1;
                q.push(e.to);
            }
        }
    }

    int ans = INF;

    // Case 1: Lennon reaches the room adjacent to the Door to Summer by himself/help from opened normal doors.
    // Then possibly the Door to Summer itself may need opening if it is normal.
    if (distL[summerRoom] < INF) {
        ans = min(ans, distL[summerRoom] + (summerType == 'N' ? 1 : 0));
    }

    // Case 2: If the Door to Summer is normal, Natsume may need to open it.
    // She must be able to reach the adjacent room.
    if (summerType == 'N' && reachN[summerRoom] && distL[summerRoom] < INF) {
        ans = min(ans, distL[summerRoom] + 1);
    }

    // In fact Case 1 already covers the same count, but keeping this explicit is fine.

    cout << ans << '\n';
    return 0;
}

