import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        char nextChar() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            return (char) c;
        }
    }

    static class Edge {
        int to, next;
        char type;
        Edge(int to, int next, char type) {
            this.to = to;
            this.next = next;
            this.type = type;
        }
    }

    static int n, m;
    static int sN, sL;
    static int[] head;
    static Edge[] edges;
    static int edgeCnt = 0;

    static void addEdge(int u, int v, char t) {
        edges[edgeCnt] = new Edge(v, head[u], t);
        head[u] = edgeCnt++;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        n = fs.nextInt();
        m = fs.nextInt();
        sN = fs.nextInt();
        sL = fs.nextInt();

        head = new int[n + 1];
        Arrays.fill(head, -1);
        edges = new Edge[2 * m];

        int summerRoom = -1;

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt();
            int b = fs.nextInt();
            char t = fs.nextChar();

            if (a == 0) summerRoom = b;
            else if (b == 0) summerRoom = a;
            else {
                addEdge(a, b, t);
                addEdge(b, a, t);
            }
        }

        // 0-1 BFS on state (NatsumeRoom, LennonRoom)
        // dist[u][v] too large; use hash map because only reachable states matter.
        long start = encode(sN, sL);
        HashMap<Long, Integer> dist = new HashMap<>(1 << 20);
        ArrayDeque<Long> dq = new ArrayDeque<>();
        dist.put(start, 0);
        dq.add(start);

        int answer = -1;

        while (!dq.isEmpty()) {
            long cur = dq.pollFirst();
            int d = dist.get(cur);
            int nr = decodeA(cur);
            int lr = decodeB(cur);

            if (lr == summerRoom) {
                answer = d;
                break;
            }

            // Lennon moves alone through L-doors (cost 0)
            for (int ei = head[lr]; ei != -1; ei = edges[ei].next) {
                Edge e = edges[ei];
                if (e.type == 'L') {
                    long nxt = encode(nr, e.to);
                    if (!dist.containsKey(nxt) || dist.get(nxt) > d) {
                        dist.put(nxt, d);
                        dq.addFirst(nxt);
                    }
                }
            }

            // Natsume moves alone through already-open normal doors:
            // We do not track opened doors explicitly.
            // Key observation:
            // Opening a normal door costs 1 exactly when Natsume first traverses it.
            // Since opened doors remain open and Lennon can use them too, the optimal
            // strategy can be modeled by charging 1 whenever Natsume traverses a normal door,
            // and 0 for Lennon traversing any already-open/small possibility.
            //
            // To make this correct without explicit door-state tracking, we allow:
            // - Natsume traversing N-door with cost 1
            // - Lennon traversing N-door only if Natsume is currently at the same room and opens it for him,
            //   which is equivalent to a joint move costing 1.
            //
            // This suffices because reusing an opened door never helps reduce the count below
            // the number of distinct N-doors Natsume needs to open along some connected explored region,
            // and any such reuse can be rearranged into an optimal sequence of these transitions.

            // Natsume moves through N-doors, opening one (cost 1)
            for (int ei = head[nr]; ei != -1; ei = edges[ei].next) {
                Edge e = edges[ei];
                if (e.type == 'N') {
                    long nxt = encode(e.to, lr);
                    if (!dist.containsKey(nxt) || dist.get(nxt) > d + 1) {
                        dist.put(nxt, d + 1);
                        dq.addLast(nxt);
                    }
                }
            }

            // If they are in the same room, Natsume can open an adjacent normal door for Lennon
            if (nr == lr) {
                for (int ei = head[lr]; ei != -1; ei = edges[ei].next) {
                    Edge e = edges[ei];
                    if (e.type == 'N') {
                        long nxt = encode(nr, e.to);
                        if (!dist.containsKey(nxt) || dist.get(nxt) > d + 1) {
                            dist.put(nxt, d + 1);
                            dq.addLast(nxt);
                        }
                    }
                }
            }
        }

        System.out.println(answer);
    }

    static long encode(int a, int b) {
        return (((long) a) << 32) ^ (b & 0xffffffffL);
    }

    static int decodeA(long x) {
        return (int) (x >>> 32);
    }

    static int decodeB(long x) {
        return (int) x;
    }
}

import heapq
from collections import defaultdict

def solve():
    import sys
    input_data = sys.stdin.read().split()
    idx = 0
    n, m = int(input_data[idx]), int(input_data[idx+1]); idx+=2
    nat_start, len_start = int(input_data[idx]), int(input_data[idx+1]); idx+=2

    graph = defaultdict(list)
    for _ in range(m):
        u, v, t = int(input_data[idx]), int(input_data[idx+1]), input_data[idx+2]; idx+=3
        graph[u].append((v, t))
        graph[v].append((u, t))

    dist = {}
    pq = [(0, nat_start, len_start)]

    while pq:
        cost, np, lp = heapq.heappop(pq)
        if lp == 0:
            print(cost)
            return
        if (np, lp) in dist:
            continue
        dist[(np, lp)] = cost

        # Lennon moves through L doors
        for (nb, t) in graph[lp]:
            if t == 'L' and (np, nb) not in dist:
                heapq.heappush(pq, (cost, np, nb))

        # Natsume moves through N doors (opens them, cost 1)
        for (nb, t) in graph[np]:
            if t == 'N' and (nb, lp) not in dist:
                heapq.heappush(pq, (cost+1, nb, lp))

        # If same room, Natsume opens N door for Lennon
        if np == lp:
            for (nb, t) in graph[lp]:
                if t == 'N' and (np, nb) not in dist:
                    heapq.heappush(pq, (cost+1, np, nb))

solve()
